'use strict';

// ═══════════════════════════════════════════════════
// FIREBASE SYNC — uses Firebase SDK (via auth.js)
// Auth token handled automatically by the SDK
// ═══════════════════════════════════════════════════

const FB_URL = 'https://bnfc-monitor-default-rtdb.europe-west1.firebasedatabase.app';

let syncPending  = false;
let syncTimer    = null;
let pollTimer    = null;
let sseConn      = null;
let isOnline     = navigator.onLine;
let isSyncing    = false;

window.addEventListener('online',  () => { isOnline = true;  updateSyncBadge(); flushPending(); startListener(); });
window.addEventListener('offline', () => { isOnline = false; updateSyncBadge(); });

// Is the user actively typing?
function isUserEditing() {
  const el = document.activeElement;
  if (!el) return false;
  return ['input','textarea','select'].includes(el.tagName.toLowerCase());
}

// ── Sync badge ──────────────────────────────────
function updateSyncBadge(state) {
  const labels = {
    offline: ['● Offline',      'offline'],
    syncing: ['↑ Syncing…',     'syncing'],
    ok:      ['✓ Synced',       'ok'],
    error:   ['⚠ Tap to retry', 'error'],
    online:  ['↻ Sync',         'online'],
  };
  const key = !isOnline ? 'offline' : (state || 'online');
  const [text, cls] = labels[key];
  const b  = document.getElementById('sync-badge');
  const bm = document.getElementById('sync-badge-mobile');
  if (b)  { b.textContent  = text; b.className  = 'sync-badge ' + cls; }
  if (bm) { bm.textContent = text; bm.className = 'sync-badge-mobile ' + cls; }
}

// ── Firebase access via window.bnfc (set by auth.js) ─
// auth.js owns the single Firebase instance and exposes
// dbRead / dbWrite / dbListen through window.bnfc

async function waitForBnfc() {
  let tries = 0;
  while (!window.bnfc && tries++ < 50) {
    await new Promise(r => setTimeout(r, 100));
  }
  if (!window.bnfc) throw new Error('Firebase not initialised');
}

async function fbRead() {
  await waitForBnfc();
  return window.bnfc.dbRead();
}

async function fbWrite(key, value) {
  await waitForBnfc();
  return window.bnfc.dbWrite(key, value);
}

async function fbWriteAll(data) {
  await waitForBnfc();
  return window.bnfc.dbWriteAll(data);
}

// ── Apply remote data ────────────────────────────
function applyRemote(data) {
  if (!data || typeof data !== 'object') return;
  let newPlayers = null, newRecords = null;
  if (data.players) { try { newPlayers = JSON.parse(data.players); } catch {} }
  if (data.records) { try { newRecords = JSON.parse(data.records); } catch {} }
  if (data.evals)   { try { const e = JSON.parse(data.evals); if (e) evals = e; } catch {} }
  if (data.matches) {
    try {
      const m = JSON.parse(data.matches);
      if (Array.isArray(m)) {
        mdMatchHistory = m;
        localStorage.setItem(MD_HISTORY_KEY, JSON.stringify(mdMatchHistory));
        if (currentTab === 'matches') renderMatchesTab();
        // Also refresh setup page history list if visible
        const setupEl = document.getElementById('md-setup');
        if (setupEl && !setupEl.classList.contains('hidden')) mdRenderHistory();
      }
    } catch {}
  }
  const pChanged = newPlayers && Array.isArray(newPlayers) && newPlayers.length > 0 &&
                   JSON.stringify(newPlayers) !== JSON.stringify(players);
  const rChanged = newRecords && typeof newRecords === 'object' &&
                   JSON.stringify(newRecords) !== JSON.stringify(records);
  if (!pChanged && !rChanged) { updateSyncBadge('ok'); return; }
  if (pChanged) players = newPlayers;
  if (rChanged) records = newRecords;
  localStorage.setItem(PLAYERS_KEY, JSON.stringify(players));
  localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
  if (isUserEditing()) { updateSyncBadge('ok'); return; }
  if (currentTab === 'squad')    { selectedPlayerId ? renderPlayerDetail(selectedPlayerId) : renderSquad(); }
  if (currentTab === 'overview') renderOverview();
  if (currentTab === 'players')  renderPlayersTable();
  if (currentTab === 'evals')    renderEvalsTab();
  updateSyncBadge('ok');
}

// ── Push to Firebase ─────────────────────────────
async function pushToFirebase() {
  if (!isOnline || isSyncing) return;
  isSyncing = true;
  updateSyncBadge('syncing');
  try {
    const payload = {
      players: JSON.stringify(players),
      records: JSON.stringify(records),
      evals:   JSON.stringify(evals),
      matches: JSON.stringify(mdMatchHistory || []),
    };
    // Prefer single atomic write; fall back to sequential writes for old auth.js
    if (window.bnfc && typeof window.bnfc.dbWriteAll === 'function') {
      await window.bnfc.dbWriteAll(payload);
    } else {
      await fbWrite('players', payload.players);
      await fbWrite('records', payload.records);
      await fbWrite('evals',   payload.evals);
      await fbWrite('matches', payload.matches);
    }
    syncPending = false;
    updateSyncBadge('ok');
  } catch(e) {
    console.error('Push failed:', e);
    updateSyncBadge('error');
  } finally { isSyncing = false; }
}

// ── Pull from Firebase ───────────────────────────
async function pullFromFirebase() {
  if (!isOnline || isUserEditing()) return;
  try {
    const data = await fbRead();
    if (data) applyRemote(data);
  } catch(e) { console.error('Pull failed:', e); }
}

// ── Schedule save ────────────────────────────────
function scheduleSave() {
  syncPending = true;
  clearTimeout(syncTimer);
  syncTimer = setTimeout(pushToFirebase, 2000);
}

async function flushPending() { if (syncPending) await pushToFirebase(); }

// ── Manual sync (badge tap) ──────────────────────
async function manualSync() {
  if (!isOnline) { updateSyncBadge(); return; }
  if (isUserEditing()) { await flushPending(); return; }
  updateSyncBadge('syncing');
  try {
    const data = await fbRead();
    if (data) applyRemote(data);
    if (syncPending) await pushToFirebase();
    else updateSyncBadge('ok');
  } catch(e) { updateSyncBadge('error'); }
}

async function doSync() { await manualSync(); }

// ── Real-time listener via window.bnfc.dbListen ──
function startListener() {
  if (pollTimer) { clearInterval(pollTimer); pollTimer = null; }
  if (sseConn)   { try { sseConn.close(); } catch {} sseConn = null; }

  // Use Firebase SDK real-time listener from auth.js
  waitForBnfc().then(() => {
    window.bnfc.dbListen(data => {
      if (!syncPending) applyRemote(data);
    });
    console.log('Firebase real-time listener active');
  }).catch(() => {
    // Fallback: poll every 30 seconds
    pollTimer = setInterval(() => {
      if (isOnline && !syncPending && !isUserEditing()) pullFromFirebase();
    }, 30000);
  });
}

// ── Storage ──────────────────────────────────────
function loadFromLocal() {
  try { records = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}'); } catch { records = {}; }
  try {
    const p = localStorage.getItem(PLAYERS_KEY);
    players = p ? JSON.parse(p) : [...DEFAULT_PLAYERS];
  } catch { players = [...DEFAULT_PLAYERS]; }
  try { photos = JSON.parse(localStorage.getItem(PHOTOS_KEY) || '{}'); } catch { photos = {}; }
  try { evals  = JSON.parse(localStorage.getItem(EVALS_KEY)   || '{}'); } catch { evals  = {}; }
  try {
    const m = localStorage.getItem(MD_HISTORY_KEY);
    mdMatchHistory = m ? JSON.parse(m) : [];
  } catch { mdMatchHistory = []; }
}

function saveLocal() {
  localStorage.setItem(PLAYERS_KEY, JSON.stringify(players));
  localStorage.setItem(STORAGE_KEY, JSON.stringify(records));
  localStorage.setItem(PHOTOS_KEY,  JSON.stringify(photos));
  localStorage.setItem(EVALS_KEY,   JSON.stringify(evals));
}

async function loadData() {
  loadFromLocal();
  renderSquad();
  renderLog();
  updateSyncBadge();
  if (!isOnline) return;
  updateSyncBadge('syncing');
  try {
    const data = await fbRead();
    if (data) {
      applyRemote(data);
    } else {
      // Nothing in Firebase yet — push local data up
      await pushToFirebase();
    }
    startListener();
  } catch(e) {
    console.error('loadData error:', e);
    updateSyncBadge('error');
  }
}

function savePlayers() { localStorage.setItem(PLAYERS_KEY, JSON.stringify(players)); scheduleSave(); }
function saveRecords()  { localStorage.setItem(STORAGE_KEY, JSON.stringify(records)); scheduleSave(); }
function savePhotos()   { localStorage.setItem(PHOTOS_KEY,  JSON.stringify(photos)); }
function saveEvals()    { localStorage.setItem(EVALS_KEY,   JSON.stringify(evals));  scheduleSave(); }


