// ---- HELPERS ----

function getPlayer(pid)    { return players.find(p => p.id === pid); }
function getRecords(pid)   { return records[pid] || []; }
function getPhoto(p) {
  if (photos[p.id]) return photos[p.id];
  if (p.photo) {
    const fname = p.photo.split('/').pop();
    if (typeof IMAGE_DATA !== 'undefined' && IMAGE_DATA[fname]) return IMAGE_DATA[fname];
  }
  return p.photo || '';
}

function getAttRate(pid) {
  const r = getRecords(pid);
  if (!r.length) return null;
  return Math.round(r.filter(x => x.attended).length / r.length * 100);
}

function getAvgEffort(pid) {
  const r = getRecords(pid).filter(x => x.attended && x.effort > 0);
  if (!r.length) return null;
  return (r.reduce((a, b) => a + b.effort, 0) / r.length).toFixed(1);
}

function getAvgAttrs(pid) {
  const r = getRecords(pid).filter(x => x.attended && x.attrs);
  if (!r.length) return null;
  const avg = {};
  ATTRS.forEach(a => {
    const vals = r.map(e => e.attrs[a.key] || 0).filter(v => v > 0);
    avg[a.key] = vals.length ? parseFloat((vals.reduce((s, v) => s + v, 0) / vals.length).toFixed(1)) : 0;
  });
  return avg;
}

function getLatestSwot(pid) {
  return [...getRecords(pid)].reverse().find(x => x.swot && Object.values(x.swot).some(v => v));
}

function getStatus(pid) {
  const att = getAttRate(pid);
  const eff = parseFloat(getAvgEffort(pid));
  const sessions = getRecords(pid).length;
  if (!sessions) return 'none';
  if (att < 60 || eff < 2.5) return 'review';
  if (att >= 80 && (isNaN(eff) || eff >= 3.5)) return 'good';
  return 'monitor';
}

function statusBadge(status) {
  const map = { good: ['badge-green','On track'], monitor: ['badge-amber','Monitor'], review: ['badge-red','Review'], none: ['badge-muted','No data'] };
  const [cls, label] = map[status] || map.none;
  return `<span class="badge ${cls}">${label}</span>`;
}

function posBadge(position) {
  if (!position) return `<span class="pos-badge pos-none">—</span>`;
  const map = { Goalkeeper: 'GK', Defender: 'DEF', Midfielder: 'MID', Forward: 'FWD' };
  const code = map[position] || 'none';
  return `<span class="pos-badge pos-${code}">${position}</span>`;
}

function makeInitials(name) {
  return name.trim().split(/\s+/).map(w => w[0]).join('').toUpperCase().slice(0, 2);
}

function makeId(name) {
  return name.toLowerCase().replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, '') + '_' + Date.now();
}

function formatDate(d) {
  if (!d) return '—';
  const dt = new Date(d + 'T00:00:00');
  return dt.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}

// ---- AVATAR RENDERING ----

function avatarImg(p, size, cssClass) {
  const photo = getPhoto(p);
  const cls = cssClass || 'player-photo';
  return `
    <img src="${photo}" alt="${p.name}" class="${cls}" style="width:${size}px;height:${size}px"
      onerror="this.style.display='none';this.nextElementSibling.style.display='flex'">
    <div class="${cls === 'player-photo' ? 'player-initials-avatar' : (cls === 'detail-avatar' ? 'detail-avatar-initials' : 'ov-avatar-initials')}"
      style="width:${size}px;height:${size}px;background:${p.bg};color:${p.color};display:none">${p.initials}</div>`;
}

// ---- RADAR CHART ----

function buildRadar(attrs, color) {
  if (!attrs) return '';
  const keys = ATTRS.map(a => a.key);
  const labels = ATTRS.map(a => a.label);
  const n = keys.length;
  const cx = 120, cy = 115, r = 78;
  const angles = keys.map((_, i) => (Math.PI * 2 * i / n) - Math.PI / 2);
  const pt = (val, ang) => ({ x: cx + r * (val / 5) * Math.cos(ang), y: cy + r * (val / 5) * Math.sin(ang) });
  let rings = '';
  for (let g = 1; g <= 5; g++) {
    const pts = angles.map(a => pt(g, a));
    rings += `<polygon points="${pts.map(p => `${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ')}" fill="${g===5?'rgba(26,107,60,0.03)':'none'}" stroke="#e2e4de" stroke-width="0.8"/>`;
  }
  const axes = angles.map(a => `<line x1="${cx}" y1="${cy}" x2="${(cx+r*Math.cos(a)).toFixed(1)}" y2="${(cy+r*Math.sin(a)).toFixed(1)}" stroke="#e2e4de" stroke-width="0.8"/>`).join('');
  const dpts = angles.map((a, i) => pt(attrs[keys[i]] || 0, a));
  const poly = `<polygon points="${dpts.map(p => `${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ')}" fill="${color}28" stroke="${color}" stroke-width="2" stroke-linejoin="round"/>`;
  const dots = dpts.map(p => `<circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="3.5" fill="${color}"/>`).join('');
  const lbls = angles.map((a, i) => {
    const lx = cx + (r + 22) * Math.cos(a), ly = cy + (r + 22) * Math.sin(a);
    return `<text x="${lx.toFixed(1)}" y="${ly.toFixed(1)}" text-anchor="middle" dominant-baseline="middle" font-size="10" font-family="DM Sans,sans-serif" fill="#7a8070">${labels[i]}</text>`;
  }).join('');
  return `<svg width="240" height="230" viewBox="0 0 240 230">${rings}${axes}${poly}${dots}${lbls}</svg>`;
}

// ---- TAB SWITCHING ----

function switchTab(name) {
  currentTab = name;
  // Sync both desktop sidebar and mobile bottom nav
  document.querySelectorAll('.nav-btn, .mobile-nav-btn').forEach(btn => btn.classList.toggle('active', btn.dataset.tab === name));
  document.querySelectorAll('.tab-section').forEach(s => s.classList.remove('active'));
  document.getElementById(`tab-${name}`).classList.add('active');
  window.scrollTo({ top: 0, behavior: 'smooth' });
  if (name === 'squad')    renderSquad();
  if (name === 'log')      renderLog();
  if (name === 'overview') renderOverview();
  if (name === 'players')  renderPlayersTable();
  if (name === 'evals')    { selectedPlayerId ? renderPlayerEvalDetail(selectedPlayerId) : renderEvalsTab(); }
  if (name === 'matchday') initMatchDay();
  if (name === 'matches')  renderMatchesTab();
}

// ---- SQUAD TAB ----

function renderSquad() {
  const grid   = document.getElementById('player-grid');
  const detail = document.getElementById('player-detail');
  const meta   = document.getElementById('squad-meta');

  if (selectedPlayerId) {
    grid.style.display = 'none';
    detail.classList.remove('hidden');
    renderPlayerDetail(selectedPlayerId);
    meta.textContent = '';
    return;
  }

  detail.classList.add('hidden');
  grid.style.display = '';
  const withData = players.filter(p => getRecords(p.id).length > 0).length;
  meta.textContent = `${withData} / ${players.length} players logged`;

  grid.innerHTML = players.map(p => {
    const att     = getAttRate(p.id);
    const sessions = getRecords(p.id).length;
    const attrs   = getAvgAttrs(p.id);
    const status  = getStatus(p.id);
    const photo   = getPhoto(p);
    const attrBars = attrs ? ATTRS.map(a =>
      `<div class="mini-attr-seg"><div class="mini-attr-fill" style="width:${Math.round((attrs[a.key]||0)/5*100)}%"></div></div>`
    ).join('') : '';
    return `<div class="player-card ${status==='review'?'has-concern':''}" style="--player-color:${p.color}" onclick="openPlayer('${p.id}')">
      <div style="position:relative;display:inline-block">
        <img src="${photo}" alt="${p.name}" class="player-photo" style="width:52px;height:52px" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'">
        <div class="player-initials-avatar" style="width:52px;height:52px;background:${p.bg};color:${p.color};display:none">${p.initials}</div>
      </div>
      <div class="player-card-name">${p.name}${p.number ? ` <span style="font-size:11px;color:#7a8070;font-weight:400">#${p.number}</span>` : ''}</div>
      <div class="player-card-meta">${sessions ? `${sessions} session${sessions>1?'s':''}<br>${att}% attendance` : 'No sessions yet'}</div>
      ${attrs ? `<div class="mini-attr-bar">${attrBars}</div>` : ''}
    </div>`;
  }).join('');
}

function openPlayer(pid) { selectedPlayerId = pid; renderSquad(); }

function renderPlayerDetail(pid) {
  const p       = getPlayer(pid);
  if (!p) return;
  const r       = getRecords(pid);
  const att     = getAttRate(pid);
  const eff     = getAvgEffort(pid);
  const sessions = r.length;
  const attended = r.filter(x => x.attended).length;
  const attrs   = getAvgAttrs(pid);
  const swotEntry = getLatestSwot(pid);
  const swot    = swotEntry ? swotEntry.swot : null;
  const lowAtt  = att !== null && att < 60;
  const photo   = getPhoto(p);

  document.getElementById('player-detail-content').innerHTML = `
    <div class="detail-header">
      <div style="position:relative;display:inline-block">
        <img src="${photo}" alt="${p.name}" class="detail-avatar" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'">
        <div class="detail-avatar-initials" style="background:${p.bg};color:${p.color};display:none">${p.initials}</div>
      </div>
      <div>
        <div class="detail-name">${p.name}${p.number ? ` <span style="font-size:16px;color:#7a8070;font-weight:400">#${p.number}</span>` : ''}</div>
        <div class="detail-sub">${p.position || 'Position not set'}${p.altPosition ? ' / ' + p.altPosition : ''} · ${sessions} session${sessions!==1?'s':''} logged</div>
        ${lowAtt ? `<div class="concern-tag">⚑ Low attendance — contact Club Welfare Officer</div>` : ''}
      </div>
      <div style="margin-left:auto;flex-shrink:0">
        <button class="btn btn-ghost" onclick="exportPlayerPDF('${pid}')" style="display:flex;align-items:center;gap:6px;font-size:13px">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
          Export PDF
        </button>
      </div>
    </div>

    <div class="stat-cards">
      <div class="stat-card">
        <div class="stat-label">Attendance</div>
        <div class="stat-value ${lowAtt?'concern':''}">${att !== null ? att+'%' : '—'}</div>
        <div class="stat-sub">${attended} / ${sessions} sessions</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Avg effort</div>
        <div class="stat-value">${eff || '—'}</div>
        <div class="stat-sub">${eff ? EFFORT_LABELS[Math.round(parseFloat(eff))] : 'No data'}</div>
      </div>
      <div class="stat-card">
        <div class="stat-label">Sessions</div>
        <div class="stat-value">${sessions}</div>
        <div class="stat-sub">${attended} present · ${sessions-attended} absent</div>
      </div>
    </div>

    ${attrs ? `<div class="card">
      <div class="card-title">Player attributes — averaged across sessions</div>
      <div class="attrs-panel">
        <div class="radar-container">${buildRadar(attrs, p.color)}</div>
        <div class="attr-bars">
          ${ATTRS.map(a => `<div class="attr-bar-row">
            <div class="attr-bar-name">${a.label}</div>
            <div class="attr-bar-track"><div class="attr-bar-fill" style="width:${Math.round((attrs[a.key]||0)/5*100)}%"></div></div>
            <div class="attr-bar-val">${attrs[a.key]>0 ? attrs[a.key].toFixed(1) : '—'}</div>
          </div>`).join('')}
        </div>
      </div>
    </div>` : ''}

    ${swot ? `<div class="card">
      <div class="card-title">Latest SWOT <span class="optional">from ${formatDate(swotEntry.date)}</span></div>
      <div class="swot-grid">
        <div class="swot-box swot-s"><div class="swot-label">Strengths</div><p>${swot.s||'<span style="opacity:0.5">Not recorded</span>'}</p></div>
        <div class="swot-box swot-w"><div class="swot-label">Weaknesses</div><p>${swot.w||'<span style="opacity:0.5">Not recorded</span>'}</p></div>
        <div class="swot-box swot-o"><div class="swot-label">Opportunities</div><p>${swot.o||'<span style="opacity:0.5">Not recorded</span>'}</p></div>
        <div class="swot-box swot-t"><div class="swot-label">Areas to improve</div><p>${swot.t||'<span style="opacity:0.5">Not recorded</span>'}</p></div>
      </div>
    </div>` : ''}

    <div class="card">
      <div class="card-title" style="display:flex;align-items:center;justify-content:space-between">
        Session history
        ${r.length ? `<button class="btn btn-ghost" style="font-size:12px;padding:4px 12px;color:#a32d2d;border-color:#f0aaa8" onclick="openResetModal('${pid}')">Reset data…</button>` : ''}
      </div>
      ${r.length ? `<div class="history-list">
        ${[...r].map((entry, fwdIdx) => { const realIdx = r.length - 1 - fwdIdx; return ''; }).join('')}
        ${[...r].reverse().map((entry, revIdx) => { const realIdx = r.length - 1 - revIdx; return `<div class="history-entry">
          <div class="history-date">${formatDate(entry.date)} · ${entry.type}</div>
          <div class="history-row">
            <span class="badge ${entry.attended?'badge-green':'badge-red'}">${entry.attended?'Present':'Absent'}</span>
            ${entry.attended && entry.effort ? `<span style="color:#e6a817;font-size:15px;letter-spacing:1px">${'★'.repeat(entry.effort)}${'☆'.repeat(5-entry.effort)}</span>` : ''}
            ${entry.notes ? `<span style="font-size:13px;color:#7a8070">${entry.notes}</span>` : ''}
          </div>
          ${entry.attrs && entry.attended ? `<div class="history-attrs">${ATTRS.filter(a=>entry.attrs[a.key]>0).map(a=>`${a.label} ${Number(entry.attrs[a.key]).toFixed(1).replace('.0','')}/5`).join(' · ')}</div>` : ''}
          <div class="history-actions">
            <button class="session-action-btn view" onclick="openSessionView('${pid}', ${realIdx})">
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
              View
            </button>
            <button class="session-action-btn edit" onclick="openSessionEdit('${pid}', ${realIdx})">
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
              Edit
            </button>
            <button class="session-action-btn delete" onclick="openSessionDelete('${pid}', ${realIdx})">
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/></svg>
              Delete
            </button>
          </div>
        </div>`; }).join('')}
      </div>` : `<div class="empty-state">No sessions logged yet.</div>`}
    </div>

    ${r.length ? `<div class="danger-zone">
      <div class="danger-zone-title">Data management</div>
      <div class="danger-zone-row">
        <div class="danger-zone-desc">Reset or clear all recorded session data for this player. Individual sessions can also be edited or deleted above.</div>
        <button class="btn btn-danger" style="white-space:nowrap" onclick="openResetModal('${pid}')">Reset data…</button>
      </div>
    </div>` : ''}`;
}

// ---- LOG SESSION TAB ----

function renderLog() {
  logState = { effort: 0, attended: true, attrs: {} };
  ATTRS.forEach(a => { logState.attrs[a.key] = 0; });
  document.getElementById('logDate').value = new Date().toISOString().slice(0, 10);
  const sel = document.getElementById('logPlayer');
  sel.innerHTML = '<option value="">— Select player —</option>' +
    [...players].sort((a,b) => a.name.localeCompare(b.name))
    .map(p => `<option value="${p.id}">${p.name}${p.number?' #'+p.number:''}</option>`).join('');
  document.querySelector('input[name="att"][value="1"]').checked = true;
  togglePresentFields(true);
  setEffort(0);
  const grid = document.getElementById('attr-log-grid');
  grid.innerHTML = ATTRS.map(a => `<div class="attr-log-row">
    <div class="attr-log-label">${a.label}<span class="pip-val" id="pipval-${a.key}">—</span></div>
    <div class="half-slider-wrap">
      <input type="range" class="half-slider" id="slider-${a.key}"
        min="0" max="10" step="1" value="0"
        data-attr="${a.key}"
        oninput="setHalfSlider('${a.key}', this.value)">
      <div class="half-slider-ticks">${[0,1,2,3,4,5].map(n=>`<span>${n}</span>`).join('')}</div>
    </div>
  </div>`).join('');
  document.getElementById('logNotes').value = '';
  ['swotS','swotW','swotO','swotT'].forEach(id => { document.getElementById(id).value = ''; });
  document.getElementById('log-msg').innerHTML = '';
}

function togglePresentFields(show) {
  document.getElementById('present-card').style.display = show ? '' : 'none';
  document.getElementById('attrs-card').style.display   = show ? '' : 'none';
}

function setEffort(n) {
  logState.effort = n;
  document.querySelectorAll('.star').forEach(s => {
    const v = parseInt(s.dataset.val);
    s.textContent = v <= n ? '★' : '☆';
    s.classList.toggle('on', v <= n);
  });
  document.getElementById('effort-hint').textContent = n > 0 ? EFFORT_LABELS[n] : 'Tap to rate';
}

function setHalfSlider(attr, rawVal) {
  // rawVal 0-10 maps to 0-5 in 0.5 steps
  const val = parseInt(rawVal) / 2;
  logState.attrs[attr] = val;
  const lbl = document.getElementById(`pipval-${attr}`);
  if (lbl) lbl.textContent = val > 0 ? val.toFixed(1).replace('.0','') + '/5' : '—';
  // Update slider fill colour
  const slider = document.getElementById(`slider-${attr}`);
  if (slider) {
    const pct = (parseInt(rawVal) / 10) * 100;
    slider.style.background = `linear-gradient(to right, var(--green) ${pct}%, var(--border) ${pct}%)`;
  }
}

function setPip(attr, val) { setHalfSlider(attr, val * 2); } // legacy compat

function saveEntry() {
  const pid   = document.getElementById('logPlayer').value;
  const date  = document.getElementById('logDate').value;
  const type  = document.getElementById('logType').value;
  const notes = document.getElementById('logNotes').value.trim();
  if (!pid)  { alert('Please select a player.'); return; }
  if (!date) { alert('Please enter a date.'); return; }
  const swot = {
    s: document.getElementById('swotS').value.trim(),
    w: document.getElementById('swotW').value.trim(),
    o: document.getElementById('swotO').value.trim(),
    t: document.getElementById('swotT').value.trim(),
  };
  // Gather slider values at save time (logState.attrs updated live by oninput)
  const entry = { date, type, attended: logState.attended, effort: logState.attended ? logState.effort : 0, attrs: logState.attended ? { ...logState.attrs } : null, notes, swot, timestamp: Date.now() };
  if (!records[pid]) records[pid] = [];
  records[pid].push(entry);
  saveRecords();
  const pname = getPlayer(pid)?.name || pid;
  renderLog();
  document.getElementById('log-msg').innerHTML = `<div class="log-success">✓ Entry saved for ${pname} — ${formatDate(date)}</div>`;
  setTimeout(() => { const m = document.getElementById('log-msg'); if (m) m.innerHTML = ''; }, 4000);
}

// ---- OVERVIEW TAB ----

function renderOverview() {
  const withData = players.filter(p => getRecords(p.id).length > 0).length;
  const review   = players.filter(p => getStatus(p.id) === 'review').length;
  const rates    = players.map(p => getAttRate(p.id)).filter(v => v !== null);
  const avgAtt   = rates.length ? Math.round(rates.reduce((a,b)=>a+b,0)/rates.length) : null;
  document.getElementById('overview-stats').innerHTML = `
    <div class="ov-stat"><div class="ov-stat-label">Squad size</div><div class="ov-stat-value">${players.length}</div></div>
    <div class="ov-stat"><div class="ov-stat-label">Players logged</div><div class="ov-stat-value">${withData}</div></div>
    <div class="ov-stat"><div class="ov-stat-label">Avg attendance</div><div class="ov-stat-value">${avgAtt!==null?avgAtt+'%':'—'}</div></div>
    <div class="ov-stat"><div class="ov-stat-label">Need review</div><div class="ov-stat-value ${review>0?'danger':''}">${review}</div></div>
    <div class="ov-stat" style="display:flex;align-items:center;justify-content:center">
      <button class="btn btn-primary" onclick="exportOverviewPDF()" style="display:flex;align-items:center;gap:6px;white-space:nowrap">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
        Export PDF
      </button>
    </div>`;
  renderTable();
}

function renderTable() {
  const search = document.getElementById('search-input').value.toLowerCase();
  const sort   = document.getElementById('sort-select').value;
  const statusOrder = { review:0, monitor:1, good:2, none:3 };
  let rows = players.map(p => ({ p, att: getAttRate(p.id), eff: getAvgEffort(p.id), sessions: getRecords(p.id).length, attrs: getAvgAttrs(p.id), status: getStatus(p.id) }));
  if (search) rows = rows.filter(r => r.p.name.toLowerCase().includes(search));
  rows.sort((a, b) => {
    if (sort === 'att')    return (b.att ?? -1) - (a.att ?? -1);
    if (sort === 'effort') return (parseFloat(b.eff)||0) - (parseFloat(a.eff)||0);
    if (sort === 'status') return statusOrder[a.status] - statusOrder[b.status];
    return a.p.name.localeCompare(b.p.name);
  });
  const photo = p => getPhoto(p);
  document.getElementById('overview-tbody').innerHTML = rows.map(({ p, att, eff, sessions, attrs, status }) => `
    <tr onclick="openPlayerFromOverview('${p.id}')">
      <td><div class="ov-player-cell">
        <img src="${photo(p)}" alt="${p.name}" class="ov-avatar" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'">
        <div class="ov-avatar-initials" style="background:${p.bg};color:${p.color};display:none">${p.initials}</div>
        ${p.name}
      </div></td>
      <td>${sessions||'—'}</td>
      <td>${att!==null?att+'%':'—'}</td>
      <td>${eff?`${'★'.repeat(Math.round(parseFloat(eff)))}${'☆'.repeat(5-Math.round(parseFloat(eff)))} ${eff}`:'—'}</td>
      ${ATTRS.map(a=>`<td class="attr-pill">${attrs&&attrs[a.key]>0?attrs[a.key].toFixed(1):'—'}</td>`).join('')}
      <td>${statusBadge(status)}</td>
    </tr>`).join('');
}

function openPlayerFromOverview(pid) { selectedPlayerId = pid; switchTab('squad'); }

// ---- PLAYERS MANAGEMENT TAB ----

function renderPlayersTable() {
  const sorted = [...players].sort((a, b) => {
    const na = parseInt(a.number) || 999, nb = parseInt(b.number) || 999;
    if (na !== nb) return na - nb;
    return a.name.localeCompare(b.name);
  });
  document.getElementById('players-tbody').innerHTML = sorted.map(p => {
    const sessions = getRecords(p.id).length;
    const photo    = getPhoto(p);
    return `<tr>
      <td><div class="ov-player-cell">
        <img src="${photo}" alt="${p.name}" class="ov-avatar" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'">
        <div class="ov-avatar-initials" style="background:${p.bg};color:${p.color};display:none">${p.initials}</div>
        ${p.name}
      </div></td>
      <td>${p.number || '—'}</td>
      <td>${posBadge(p.position)}</td>
      <td>${p.altPosition ? posBadge(p.altPosition) : '<span style="color:#7a8070">—</span>'}</td>
      <td>${formatDate(p.dob)}</td>
      <td>${formatDate(p.joined)}</td>
      <td>${sessions || '—'}</td>
      <td>
        <div class="action-cell">
          <button class="action-btn edit" onclick="openEditModal('${p.id}')">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
            Edit
          </button>
          <button class="action-btn delete" onclick="openDeleteModal('${p.id}')">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/><path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"/></svg>
            Remove
          </button>
        </div>
      </td>
    </tr>`;
  }).join('');
}

// ---- MODAL: ADD / EDIT ----

function buildColorPicker(selectedColor) {
  document.getElementById('color-picker').innerHTML = AVATAR_PALETTE.map((c, i) => `
    <div class="color-swatch ${c.color === selectedColor ? 'selected' : ''}" style="background:${c.color}"
      data-idx="${i}" onclick="selectColor(${i})"></div>`).join('');
}

function selectColor(idx) {
  selectedColorIdx = idx;
  document.querySelectorAll('.color-swatch').forEach((s, i) => s.classList.toggle('selected', i === idx));
  updateModalAvatar();
}

function updateModalAvatar() {
  const name = document.getElementById('modal-name').value.trim();
  const initials = name ? makeInitials(name) : '?';
  const palette = AVATAR_PALETTE[selectedColorIdx];
  const initialsEl = document.getElementById('modal-photo-initials');
  initialsEl.textContent = initials;
  initialsEl.style.background = palette.bg;
  initialsEl.style.color      = palette.color;
  if (!modalPhotoData) {
    document.getElementById('modal-photo-preview').style.display = 'none';
    initialsEl.style.display = 'flex';
  }
}

function openAddModal() {
  modalPhotoData = null;
  selectedColorIdx = 0;
  document.getElementById('modal-player-id').value = '';
  document.getElementById('modal-title').textContent = 'Add player';
  document.getElementById('modal-name').value     = '';
  document.getElementById('modal-number').value       = '';
  document.getElementById('modal-position').value     = '';
  document.getElementById('modal-alt-position').value = '';
  document.getElementById('modal-dob').value          = '';
  document.getElementById('modal-joined').value   = '';
  document.getElementById('modal-notes-field').value = '';
  document.getElementById('modal-photo-preview').style.display = 'none';
  document.getElementById('modal-photo-remove').style.display  = 'none';
  document.getElementById('modal-photo-input').value = '';
  buildColorPicker(AVATAR_PALETTE[0].color);
  updateModalAvatar();
  document.getElementById('player-modal').classList.remove('hidden');
}

function openEditModal(pid) {
  const p = getPlayer(pid);
  if (!p) return;
  modalPhotoData = photos[pid] || null;
  selectedColorIdx = AVATAR_PALETTE.findIndex(c => c.color === p.color);
  if (selectedColorIdx < 0) selectedColorIdx = 0;
  document.getElementById('modal-player-id').value     = pid;
  document.getElementById('modal-title').textContent   = 'Edit player';
  document.getElementById('modal-name').value          = p.name;
  document.getElementById('modal-number').value        = p.number || '';
  document.getElementById('modal-position').value      = p.position || '';
  document.getElementById('modal-alt-position').value  = p.altPosition || '';
  document.getElementById('modal-dob').value           = p.dob || '';
  document.getElementById('modal-joined').value        = p.joined || '';
  document.getElementById('modal-notes-field').value   = p.notes || '';
  document.getElementById('modal-photo-input').value   = '';
  const preview = document.getElementById('modal-photo-preview');
  const removeBtn = document.getElementById('modal-photo-remove');
  if (modalPhotoData) {
    preview.src = modalPhotoData;
    preview.style.display = 'block';
    document.getElementById('modal-photo-initials').style.display = 'none';
    removeBtn.style.display = 'inline-flex';
  } else {
    preview.style.display = 'none';
    removeBtn.style.display = 'none';
  }
  buildColorPicker(p.color);
  updateModalAvatar();
  document.getElementById('player-modal').classList.remove('hidden');
}

function closeModal() {
  document.getElementById('player-modal').classList.add('hidden');
}

function savePlayer() {
  const name = document.getElementById('modal-name').value.trim();
  if (!name) { alert('Please enter a player name.'); return; }

  const pid      = document.getElementById('modal-player-id').value;
  const palette  = AVATAR_PALETTE[selectedColorIdx];
  const initials = makeInitials(name);
  const number      = document.getElementById('modal-number').value.trim();
  const position    = document.getElementById('modal-position').value;
  const altPosition = document.getElementById('modal-alt-position').value;
  const dob         = document.getElementById('modal-dob').value;
  const joined      = document.getElementById('modal-joined').value;
  const notes       = document.getElementById('modal-notes-field').value.trim();

  if (pid) {
    // Edit existing
    const idx = players.findIndex(p => p.id === pid);
    if (idx >= 0) {
      players[idx] = { ...players[idx], name, initials, color: palette.color, bg: palette.bg, number, position, altPosition, dob, joined, notes };
    }
    if (modalPhotoData) photos[pid] = modalPhotoData;
    else delete photos[pid];
  } else {
    // Add new
    const id = makeId(name);
    const newPlayer = { id, name, initials, color: palette.color, bg: palette.bg, photo: '', number, position, altPosition, dob, joined, notes };
    players.push(newPlayer);
    if (modalPhotoData) photos[id] = modalPhotoData;
  }

  savePlayers();
  savePhotos();
  closeModal();
  renderPlayersTable();
}

// ---- MODAL: DELETE ----

function openDeleteModal(pid) {
  const p = getPlayer(pid);
  if (!p) return;
  deleteTargetId = pid;
  const sessions = getRecords(pid).length;
  document.getElementById('delete-modal-text').textContent =
    `You are about to remove ${p.name} from the squad.${sessions ? ` They have ${sessions} session record${sessions>1?'s':''} saved.` : ''}`;
  document.getElementById('delete-modal').classList.remove('hidden');
}

function closeDeleteModal() {
  deleteTargetId = null;
  document.getElementById('delete-modal').classList.add('hidden');
}

function confirmDelete() {
  if (!deleteTargetId) return;
  players = players.filter(p => p.id !== deleteTargetId);
  delete records[deleteTargetId];
  delete photos[deleteTargetId];
  savePlayers();
  saveRecords();
  savePhotos();
  if (selectedPlayerId === deleteTargetId) selectedPlayerId = null;
  closeDeleteModal();
  renderPlayersTable();
}

// ---- PHOTO UPLOAD ----

function handlePhotoUpload(file) {
  if (!file || !file.type.startsWith('image/')) return;
  if (file.size > 2 * 1024 * 1024) { alert('Photo must be under 2MB.'); return; }
  const reader = new FileReader();
  reader.onload = e => {
    modalPhotoData = e.target.result;
    const preview = document.getElementById('modal-photo-preview');
    preview.src = modalPhotoData;
    preview.style.display = 'block';
    document.getElementById('modal-photo-initials').style.display = 'none';
    document.getElementById('modal-photo-remove').style.display = 'inline-flex';
  };
  reader.readAsDataURL(file);
}


// ---- SESSION EDIT MODAL ----

function openSessionEdit(pid, idx) {
  const entry = getRecords(pid)[idx];
  if (!entry) return;
  sessionEditPid = pid;
  sessionEditIdx = idx;
  editEffort = entry.effort || 0;

  document.getElementById('session-edit-pid').value   = pid;
  document.getElementById('session-edit-idx').value   = idx;
  document.getElementById('session-edit-date').value  = entry.date || '';
  document.getElementById('session-edit-type').value  = entry.type || 'Training';
  document.getElementById('session-edit-notes').value = entry.notes || '';

  // Attendance
  const attVal = entry.attended ? '1' : '0';
  document.querySelectorAll('input[name="edit-att"]').forEach(r => { r.checked = r.value === attVal; });
  toggleEditPresentFields(entry.attended);

  // Effort stars
  setEditEffort(editEffort);

  // Attrs
  buildEditAttrs(entry.attrs || {});

  // SWOT
  const swot = entry.swot || {};
  document.getElementById('edit-swot-s').value = swot.s || '';
  document.getElementById('edit-swot-w').value = swot.w || '';
  document.getElementById('edit-swot-o').value = swot.o || '';
  document.getElementById('edit-swot-t').value = swot.t || '';

  const p = getPlayer(pid);
  document.getElementById('session-edit-title').textContent = `Edit session — ${p ? p.name : ''}`;
  document.getElementById('session-edit-modal').classList.remove('hidden');
}

function closeSessionEdit() {
  document.getElementById('session-edit-modal').classList.add('hidden');
  sessionEditPid = null;
  sessionEditIdx = null;
}

function toggleEditPresentFields(show) {
  document.getElementById('session-edit-present-fields').style.display = show ? '' : 'none';
}

function setEditEffort(n) {
  editEffort = n;
  document.querySelectorAll('.edit-star').forEach(s => {
    const v = parseInt(s.dataset.val);
    s.textContent = v <= n ? '★' : '☆';
    s.classList.toggle('on', v <= n);
  });
  document.getElementById('edit-effort-label').textContent = n > 0 ? EFFORT_LABELS[n] : '—';
}

function buildEditAttrs(existing) {
  const container = document.getElementById('session-edit-attrs');
  container.innerHTML = ATTRS.map(a => {
    const val = existing[a.key] || 0;
    const rawVal = Math.round(val * 2); // convert 0-5 to 0-10
    const display = val > 0 ? val.toFixed(1).replace('.0','') + '/5' : '—';
    return `<div class="edit-pip-row">
      <div class="edit-pip-label">${a.label}</div>
      <div class="half-slider-wrap" style="flex:1">
        <input type="range" class="half-slider" id="epip-slider-${a.key}"
          min="0" max="10" step="1" value="${rawVal}" data-attr="${a.key}"
          oninput="updateEditAttrLabel('${a.key}', this.value)">
        <div class="half-slider-ticks">${[0,1,2,3,4,5].map(n=>`<span>${n}</span>`).join('')}</div>
      </div>
      <div class="edit-pip-val" id="epipval-${a.key}">${display}</div>
    </div>`;
  }).join('');
}

function updateEditAttrLabel(attr, rawVal) {
  const val = parseInt(rawVal) / 2;
  const lbl = document.getElementById(`epipval-${attr}`);
  if (lbl) lbl.textContent = val > 0 ? val.toFixed(1).replace('.0','') + '/5' : '—';
  const slider = document.getElementById(`epip-slider-${attr}`);
  if (slider) {
    const pct = (parseInt(rawVal) / 10) * 100;
    slider.style.background = `linear-gradient(to right, var(--green) ${pct}%, var(--border) ${pct}%)`;
  }
}

function saveSessionEdit() {
  const pid  = document.getElementById('session-edit-pid').value;
  const idx  = parseInt(document.getElementById('session-edit-idx').value);
  if (!records[pid] || !records[pid][idx]) { closeSessionEdit(); return; }

  const attended = document.querySelector('input[name="edit-att"]:checked')?.value === '1';

  // Gather half-point slider values
  const attrs = {};
  ATTRS.forEach(a => {
    const slider = document.getElementById(`epip-slider-${a.key}`);
    attrs[a.key] = slider ? parseInt(slider.value) / 2 : 0;
  });

  records[pid][idx] = {
    ...records[pid][idx],
    date:     document.getElementById('session-edit-date').value,
    type:     document.getElementById('session-edit-type').value,
    attended,
    effort:   attended ? editEffort : 0,
    attrs:    attended ? attrs : null,
    notes:    document.getElementById('session-edit-notes').value.trim(),
    swot: {
      s: document.getElementById('edit-swot-s').value.trim(),
      w: document.getElementById('edit-swot-w').value.trim(),
      o: document.getElementById('edit-swot-o').value.trim(),
      t: document.getElementById('edit-swot-t').value.trim(),
    },
  };

  saveRecords();
  closeSessionEdit();
  renderPlayerDetail(pid);
}

// ---- SESSION DELETE ----

function openSessionDelete(pid, idx) {
  const entry = getRecords(pid)[idx];
  if (!entry) return;
  sessionDeletePid = pid;
  sessionDeleteIdx = idx;
  const p = getPlayer(pid);
  document.getElementById('session-delete-text').textContent =
    `Delete the ${entry.type} session on ${formatDate(entry.date)} for ${p ? p.name : pid}?`;
  document.getElementById('session-delete-modal').classList.remove('hidden');
}

function closeSessionDelete() {
  document.getElementById('session-delete-modal').classList.add('hidden');
  sessionDeletePid = null;
  sessionDeleteIdx = null;
}

function confirmSessionDelete() {
  if (sessionDeletePid === null || sessionDeleteIdx === null) return;
  records[sessionDeletePid].splice(sessionDeleteIdx, 1);
  if (records[sessionDeletePid].length === 0) delete records[sessionDeletePid];
  saveRecords();
  closeSessionDelete();
  renderPlayerDetail(sessionDeletePid);
}

// ---- RESET DATA MODAL ----

function openResetModal(pid) {
  resetTargetPid = pid;
  const p = getPlayer(pid);
  const sessions = getRecords(pid).length;
  document.getElementById('reset-modal-title').textContent = `Reset data — ${p ? p.name : ''}`;
  document.getElementById('reset-modal-desc').textContent =
    `${p ? p.name : 'This player'} has ${sessions} session record${sessions !== 1 ? 's' : ''}. Choose what to reset:`;
  document.querySelector('input[name="reset-scope"][value="sessions"]').checked = true;
  document.getElementById('reset-modal').classList.remove('hidden');
}

function closeResetModal() {
  document.getElementById('reset-modal').classList.add('hidden');
  resetTargetPid = null;
}

function confirmReset() {
  if (!resetTargetPid) return;
  const scope = document.querySelector('input[name="reset-scope"]:checked')?.value;
  delete records[resetTargetPid];
  saveRecords();
  closeResetModal();
  renderPlayerDetail(resetTargetPid);
}


