function pdfHeader(logoSrc) {
  return `
    <div class="pdf-header">
      <img class="pdf-logo" src="${logoSrc}" onerror="this.style.display='none'">
      <div>
        <div style="font-size:18px;font-weight:700;color:#1a1c18">Barnet Nightingales FC</div>
        <div class="pdf-club">Player Monitor — Season 2026/27</div>
      </div>
      <div class="pdf-meta">
        Generated: ${new Date().toLocaleDateString('en-GB', {day:'numeric',month:'long',year:'numeric'})}<br>
        Confidential — Club use only
      </div>
    </div>`;
}

function pdfStatusBadge(status) {
  const map = { good:'badge-green', monitor:'badge-amber', review:'badge-red', none:'badge-muted' };
  const labels = { good:'On track', monitor:'Monitor', review:'Review', none:'No data' };
  return `<span class="badge ${map[status]||'badge-muted'}">${labels[status]||'—'}</span>`;
}

function pdfRadar(attrs, color) {
  if (!attrs) return '';
  const keys   = ATTRS.map(a => a.key);
  const labels = ATTRS.map(a => a.label);
  const n = keys.length;
  const cx = 110, cy = 110, r = 75;
  const angles = keys.map((_, i) => (Math.PI * 2 * i / n) - Math.PI / 2);
  const pt = (val, ang) => ({ x: cx + r * (val / 5) * Math.cos(ang), y: cy + r * (val / 5) * Math.sin(ang) });
  let rings = '';
  for (let g = 1; g <= 5; g++) {
    const pts = angles.map(a => pt(g, a));
    rings += `<polygon points="${pts.map(p=>`${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ')}" fill="none" stroke="#e2e4de" stroke-width="0.8"/>`;
  }
  const axes = angles.map(a => `<line x1="${cx}" y1="${cy}" x2="${(cx+r*Math.cos(a)).toFixed(1)}" y2="${(cy+r*Math.sin(a)).toFixed(1)}" stroke="#e2e4de" stroke-width="0.8"/>`).join('');
  const dpts = angles.map((a, i) => pt(attrs[keys[i]] || 0, a));
  const poly = `<polygon points="${dpts.map(p=>`${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ')}" fill="${color}30" stroke="${color}" stroke-width="2" stroke-linejoin="round"/>`;
  const dots = dpts.map(p => `<circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="3" fill="${color}"/>`).join('');
  const lbls = angles.map((a, i) => {
    const lx = cx + (r + 22) * Math.cos(a), ly = cy + (r + 22) * Math.sin(a);
    return `<text x="${lx.toFixed(1)}" y="${ly.toFixed(1)}" text-anchor="middle" dominant-baseline="middle" font-size="9" font-family="Arial,sans-serif" fill="#7a8070">${labels[i]}</text>`;
  }).join('');
  return `<svg width="220" height="220" viewBox="0 0 220 220">${rings}${axes}${poly}${dots}${lbls}</svg>`;
}

// ── Per-player PDF ────────────────────────────────────────

function exportPlayerPDF(pid) {
  const p        = getPlayer(pid);
  if (!p) return;
  const r        = getRecords(pid);
  const att      = getAttRate(pid);
  const eff      = getAvgEffort(pid);
  const sessions = r.length;
  const attended = r.filter(x => x.attended).length;
  const attrs    = getAvgAttrs(pid);
  const swotEntry= getLatestSwot(pid);
  const swot     = swotEntry ? swotEntry.swot : null;
  const lowAtt   = att !== null && att < 60;
  const photo    = getPhoto(p);
  const logoSrc  = document.querySelector('.logo-img')?.src || '';

  const attrsHtml = attrs ? `
    <div class="section">
      <div class="section-title">Player attributes — averaged across all sessions</div>
      <div class="attrs-row">
        ${pdfRadar(attrs, p.color)}
        <div class="attr-bars" style="padding-top:10px">
          ${ATTRS.map(a => `
            <div class="attr-bar-row">
              <div class="attr-bar-name">${a.label}</div>
              <div class="attr-bar-track"><div class="attr-bar-fill" style="width:${Math.round((attrs[a.key]||0)/5*100)}%"></div></div>
              <div class="attr-bar-val">${attrs[a.key] > 0 ? Number(attrs[a.key]).toFixed(1) : '—'}</div>
            </div>`).join('')}
        </div>
      </div>
    </div>` : '';

  const swotHtml = swot ? `
    <div class="section">
      <div class="section-title">Latest SWOT — ${formatDate(swotEntry.date)}</div>
      <div class="swot-grid">
        <div class="swot-box swot-s"><div class="swot-label">Strengths</div><div class="swot-text">${swot.s || '—'}</div></div>
        <div class="swot-box swot-w"><div class="swot-label">Weaknesses</div><div class="swot-text">${swot.w || '—'}</div></div>
        <div class="swot-box swot-o"><div class="swot-label">Opportunities</div><div class="swot-text">${swot.o || '—'}</div></div>
        <div class="swot-box swot-t"><div class="swot-label">Areas to improve</div><div class="swot-text">${swot.t || '—'}</div></div>
      </div>
    </div>` : '';

  const historyHtml = r.length ? `
    <div class="section">
      <div class="section-title">Session history (${r.length} sessions)</div>
      ${[...r].reverse().map(entry => `
        <div class="history-entry">
          <div class="history-date">${formatDate(entry.date)} · ${entry.type}</div>
          <div class="history-row">
            <span class="badge ${entry.attended ? 'badge-green' : 'badge-red'}">${entry.attended ? 'Present' : 'Absent'}</span>
            ${entry.attended && entry.effort ? `<span style="color:#e6a817">★ ${entry.effort}/5 effort</span>` : ''}
            ${entry.notes ? `<span style="color:#7a8070">${entry.notes}</span>` : ''}
          </div>
          ${entry.attrs && entry.attended ? `<div class="history-attrs">${ATTRS.filter(a=>entry.attrs[a.key]>0).map(a=>`${a.label} ${Number(entry.attrs[a.key]).toFixed(1)}`).join(' · ')}</div>` : ''}
        </div>`).join('')}
    </div>` : '';

  const html = `<!DOCTYPE html><html><head><meta charset="UTF-8">
    <title>BNFC — ${p.name}</title>
    <style>${pdfStyles()}</style></head><body><div class="page">
    ${pdfHeader(logoSrc)}
    <div class="player-header">
      <img class="player-avatar-pdf" src="${photo}" onerror="this.style.display='none'">
      <div>
        <div class="player-title">${p.name}${p.number ? ' <span style="font-weight:400;color:#7a8070">#' + p.number + '</span>' : ''}</div>
        <div class="player-sub">${p.position || '—'}${p.altPosition ? ' / ' + p.altPosition : ''}${p.dob ? ' · DOB: ' + formatDate(p.dob) : ''}</div>
        ${lowAtt ? '<div class="concern">⚑ Low attendance — contact Club Welfare Officer</div>' : ''}
      </div>
    </div>
    <div class="stat-row">
      <div class="stat-box ${lowAtt ? 'warn' : ''}">
        <div class="stat-box-label">Attendance</div>
        <div class="stat-box-val">${att !== null ? att + '%' : '—'}</div>
        <div class="stat-box-sub">${attended} / ${sessions} sessions</div>
      </div>
      <div class="stat-box">
        <div class="stat-box-label">Avg effort</div>
        <div class="stat-box-val">${eff || '—'}</div>
        <div class="stat-box-sub">${eff ? EFFORT_LABELS[Math.round(parseFloat(eff))] : 'No data'}</div>
      </div>
      <div class="stat-box">
        <div class="stat-box-label">Sessions</div>
        <div class="stat-box-val">${sessions}</div>
        <div class="stat-box-sub">${attended} present · ${sessions - attended} absent</div>
      </div>
    </div>
    ${attrsHtml}
    ${swotHtml}
    ${historyHtml}
    <div class="footer">
      <span>Barnet Nightingales FC — Player Monitor 2026/27</span>
      <span>Confidential — ${p.name}</span>
    </div>
  </div></body></html>`;

  openPrintWindow(html, `BNFC_${p.name.replace(/\s+/g,'_')}`);
}

